Here’s a small Flask app with persistent storage and a hard limit of 20 seats. SQLite transactions prevent simultaneous signups from taking the same last seat.

Save as `app.py`:

```python
import os
import re
import sqlite3

from flask import Flask, redirect, render_template_string, request, url_for

app = Flask(__name__)
DATABASE = os.environ.get("DATABASE", "workshop.db")
CAPACITY = 20

PAGE = """
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workshop signup</title>
  <style>
    body {
      font-family: system-ui, sans-serif;
      background: #f3f5fa;
      color: #182033;
      margin: 0;
      padding: 3rem 1rem;
    }
    main {
      max-width: 420px;
      margin: auto;
      padding: 2rem;
      background: white;
      border-radius: 12px;
      box-shadow: 0 8px 30px #18203315;
    }
    h1 { margin-top: 0; }
    label { display: block; margin-top: 1rem; font-weight: 600; }
    input {
      box-sizing: border-box;
      width: 100%;
      padding: .7rem;
      margin-top: .4rem;
      border: 1px solid #aab2c2;
      border-radius: 6px;
      font: inherit;
    }
    button {
      width: 100%;
      margin-top: 1.4rem;
      padding: .8rem;
      background: #344ccf;
      color: white;
      border: 0;
      border-radius: 6px;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
    }
    .notice { padding: .8rem; background: #edf1ff; border-radius: 6px; }
    .error { background: #fff0f0; color: #9b2020; }
  </style>
</head>
<body>
  <main>
    <h1>Workshop signup</h1>
    <p>{{ remaining }} of {{ capacity }} seats remaining</p>

    {% if message %}
      <p class="notice {{ 'error' if error else '' }}" role="status">
        {{ message }}
      </p>
    {% endif %}

    {% if remaining > 0 and not success %}
      <form method="post">
        <label for="name">Name</label>
        <input id="name" name="name" required maxlength="100"
               value="{{ name }}" autocomplete="name">

        <label for="email">Email</label>
        <input id="email" name="email" type="email" required maxlength="254"
               value="{{ email }}" autocomplete="email">

        <button type="submit">Reserve my seat</button>
      </form>
    {% elif remaining == 0 and not success %}
      <p>Sorry, this workshop is full.</p>
    {% endif %}
  </main>
</body>
</html>
"""

def connect():
    db = sqlite3.connect(DATABASE, timeout=10)
    db.execute("PRAGMA busy_timeout = 10000")
    return db

def init_db():
    with connect() as db:
        db.execute("""
            CREATE TABLE IF NOT EXISTS signups (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                email TEXT NOT NULL UNIQUE,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            )
        """)

@app.route("/", methods=["GET", "POST"])
def signup():
    name = ""
    email = ""
    message = ""
    error = False
    success = request.args.get("success") == "1"

    if success:
        message = "You're signed up! Your seat is reserved."

    if request.method == "POST":
        name = request.form.get("name", "").strip()
        email = request.form.get("email", "").strip().lower()

        if not name or len(name) > 100:
            message, error = "Please enter a name of up to 100 characters.", True
        elif len(email) > 254 or not re.fullmatch(r"[^\\s@]+@[^\\s@]+\\.[^\\s@]+", email):
            message, error = "Please enter a valid email address.", True
        else:
            db = connect()
            try:
                # Lock before checking capacity so concurrent requests cannot overbook.
                db.execute("BEGIN IMMEDIATE")
                count = db.execute("SELECT COUNT(*) FROM signups").fetchone()[0]
                existing = db.execute(
                    "SELECT 1 FROM signups WHERE email = ?", (email,)
                ).fetchone()

                if existing:
                    message, error = "This email is already signed up.", True
                elif count >= CAPACITY:
                    message, error = "Sorry, the workshop is full.", True
                else:
                    db.execute(
                        "INSERT INTO signups (name, email) VALUES (?, ?)",
                        (name, email),
                    )
                    db.commit()
                    return redirect(url_for("signup", success=1))
            finally:
                db.close()

    with connect() as db:
        count = db.execute("SELECT COUNT(*) FROM signups").fetchone()[0]

    return render_template_string(
        PAGE, remaining=max(0, CAPACITY - count), capacity=CAPACITY,
        name=name, email=email, message=message, error=error, success=success,
    )

init_db()

if __name__ == "__main__":
    app.run(debug=True)
```

Run it:

```bash
pip install flask
python app.py
```

Open `http://127.0.0.1:5000`. Signups are stored in `workshop.db`. For deployment, use a production server and persistent shared storage; don’t run Flask’s debug server publicly.

